import os
os.environ["CXX"] = "hipcc"
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

swish_scale_cpp = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;

__global__ void swish_scale_kernel(const float* x, float* out, float scale, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx &lt; size) {
        float val = x[idx];
        float sig = 1.0f / (1.0f + expf(-val));
        out[idx] = val * sig * scale;
    }
}

torch::Tensor swish_scale_hip(torch::Tensor x, torch::Tensor scale_t) {
    torch::Tensor out = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;
    float scale = *scale_t.data_ptr&lt;float&gt;();
    swish_scale_kernel&lt;&lt;&lt;grid_size, block_size&gt;&gt;&gt;(x.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), scale, size);
    return out;
}
"""

swish_scale = load_inline(
    name="swish_scale",
    cpp_sources=swish_scale_cpp,
    functions=["swish_scale_hip"],
    verbose=True,
)

batch_size = 128
in_features = 32768
out_features = 32768
scaling_factor = 2.0

def get_inputs():
    return [torch.rand(batch_size, in_features)]

def get_init_inputs():
    return [in_features, out_features, scaling_factor]

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.scaling_factor = scaling_factor
        self.swish_scale = swish_scale

    def forward(self, x):
        x = self.linear(x)
        scale_t = torch.tensor(self.scaling_factor, dtype=torch.float32, device=x.device)
        return self.swish_scale.swish_scale_hip(x, scale_t)

