fused_cpp_source = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;ATen/cuda/CUDAContext.h&gt;
#include &lt;cmath&gt;

__global__ void fused_kernel(const float* x, float* out, float s1, float s2, size_t size) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx &lt; size) {
        float val = x[idx] - s1;
        out[idx] = tanhf(val) - s2;
    }
}
torch::Tensor fused_tanh_sub(torch::Tensor x, float s1, float s2) {
    auto out = torch::zeros_like(x);
    size_t size = x.numel();
    const int block_size = 256;
    const size_t num_blocks = (size + block_size - 1) / block_size;
    fused_kernel&lt;&lt;&lt;num_blocks, block_size&gt;&gt;&gt;(x.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), s1, s2, size);
    return out;
}
"""

fused = load_inline(
    name="fused_tanh",
    cpp_sources=fused_cpp_source,
    functions=["fused_tanh_sub"],
    verbose=True,
)

batch_size = 128
in_channels = 64
out_channels = 128
height, width = 128, 128
kernel_size = 3
subtract1_value = 0.5
subtract2_value = 0.2
kernel_size_pool = 2

def get_inputs():
    return [torch.rand(batch_size, in_channels, height, width)]

def get_init_inputs():
    return [in_channels, out_channels, kernel_size, subtract1_value, subtract2_value, kernel_size_pool]

class ModelNew(nn.Module):
    """
    Model that performs a convolution, subtraction, tanh activation, subtraction and average pooling.
    """
    def __init__(self, in_channels, out_channels, kernel_size, subtract1_value, subtract2_value, kernel_size_pool):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.subtract1_value = subtract1_value
        self.subtract2_value = subtract2_value
        self.avgpool = nn.AvgPool2d(kernel_size_pool)
        self.fused = fused

    def forward(self, x):
        x = self.conv(x)
        x = self.fused.fused_tanh_sub(x, self.subtract1_value, self.subtract2_value)
        x = self.avgpool(x)
        return x

