import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

cpp_source = """
#include <hip/hip_runtime.h>

__device__ float gelu(float x) {
    constexpr float k1 = 0.7978845608f;
    constexpr float k2 = 0.044715f;
    float x3 = x * x * x;
    float inner = x + k2 * x3;
    inner = k1 * inner;
    return 0.5f * x * (1.0f + tanhf(inner));
}

__global__ void fused_linear_div_gelu_kernel(
    const float* x,
    const float* weight,
    const float* bias,
    float divisor,
    float* out,
    int B, int N, int K
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx &lt;= B * N) return;
    int b = idx / N;
    int n = idx % N;
    float accum = bias[n];
    for (int k = 0; k &lt; K; ++k) {
        accum += x[ b * K + k ] * weight[ n * K + k ];
    }
    float val = accum / divisor;
    out[ b * N + n ] = gelu(val);
}

torch::Tensor fused_linear_div_gelu_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double divisor
) {
    int B = x.size(0);
    int K = x.size(1);
    int N = weight.size(0);
    torch::Tensor out = torch::empty({B, N}, x.options());
    float div = static_cast&lt;float&gt;(divisor);
    const int BS = 256;
    dim3 block(BS);
    dim3 grid( (B * N + BS - 1) / BS );
    fused_linear_div_gelu_kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;(
        x.data_ptr&lt;float&gt;(),
        weight.data_ptr&lt;float&gt;(),
        bias.data_ptr&lt;float&gt;(),
        div,
        out.data_ptr&lt;float&gt;(),
        B, N, K
    );
    return out;
}
"""

custom_fused = load_inline(
    name="fused",
    cpp_sources=cpp_source,
    functions=["fused_linear_div_gelu_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, input_size, output_size, divisor):
        super().__init__()
        self.weight = nn.Parameter(torch.empty((output_size, input_size)))
        self.bias = nn.Parameter(torch.empty((output_size,)))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        nn.init.zeros_(self.bias)
        self.divisor = divisor

    def forward(self, x):
        return custom_fused.fused_linear_div_gelu_hip(x, self.weight, self.bias, self.divisor)

