import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_source = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;

__global__ void conv2d_kernel(const float* input, const float* weight, const float* bias, float* output,
                              const int N, const int Cin, const int Cout, const int Hin, const int Win, const int K, const int out_h, const int out_w) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_out = N * Cout * out_h * out_w;
    if (idx &gt;= total_out) return;
    int b = idx / (Cout * out_h * out_w);
    int rest = idx % (Cout * out_h * out_w);
    int cout_idx = rest / (out_h * out_w);
    int oh_ow = rest % (out_h * out_w);
    int oh = oh_ow / out_w;
    int ow = oh_ow % out_w;
    float sum = bias[cout_idx];
    for (int cin = 0; cin &lt; Cin; ++cin) {
        for (int ky = 0; ky &lt; K; ++ky) {
            int ih = oh + ky;
            for (int kx = 0; kx &lt; K; ++kx) {
                int iw = ow + kx;
                float i_val = input[ ((b * Cin + cin) * Hin + ih) * Win + iw ];
                int w_idx = ((cout_idx * Cin + cin) * K + ky) * K + kx;
                float w_val = weight[w_idx];
                sum += i_val * w_val;
            }
        }
    }
    int out_idx = ((b * Cout + cout_idx) * out_h + oh) * out_w + ow;
    output[out_idx] = sum;
}

torch::Tensor conv2d_bn_scale_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    auto N = input.size(0);
    auto Cin = input.size(1);
    auto Hin = input.size(2);
    auto Win = input.size(3);
    auto Cout = weight.size(0);
    auto Kh = weight.size(2);
    auto Kw = weight.size(3);
    int K = Kh; // assume square
    auto out_h = Hin - K + 1;
    auto out_w = Win - K + 1;
    auto opts = input.options();
    auto output = torch::empty({N, Cout, out_h, out_w}, opts);
    int total_out = N * Cout * out_h * out_w;
    const int block_size = 256;
    int grid_size = (total_out + block_size - 1) / block_size;
    hipLaunchKernelGGL(
        HIP_KERNEL_NAME(conv2d_kernel),
        dim3(grid_size),
        dim3(block_size),
        0, 0,
        input.data_ptr&lt;float&gt;(),
        weight.data_ptr&lt;float&gt;(),
        bias.data_ptr&lt;float&gt;(),
        output.data_ptr&lt;float&gt;(),
        N, Cin, Cout, Hin, Win, K, (int)out_h, (int)out_w
    );
    return output;
}
"""

conv_hip_module = load_inline(
    name="fused_conv_bn",
    cpp_sources=cpp_source,
    functions=["conv2d_bn_scale_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, bias=True)
        self.bn = nn.BatchNorm2d(out_channels)
        self.scaling_factor = scaling_factor
        self.conv_hip = conv_hip_module

    def forward(self, x):
        eps = self.bn.eps
        denom = torch.sqrt(self.bn.running_var + eps)
        eff_gamma = self.bn.weight / denom * self.scaling_factor
        conv_bias = self.conv.bias
        eff_bias = ((conv_bias - self.bn.running_mean) * eff_gamma + self.bn.bias * self.scaling_factor)
        eff_weight = self.conv.weight * eff_gamma.view(self.conv.out_channels, 1, 1, 1)
        out = self.conv_hip.conv2d_bn_scale_hip(x, eff_weight, eff_bias)
        return out

