__device__ float gelu(float x) {
    constexpr float k1 = 0.7978845608f;
    constexpr float k2 = 0.044715f;
    float x3 = x * x * x;
    float inner = k1 * (x + k2 * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

__global__ void fused_linear_div_gelu_kernel(
    const float* x,
    const float* weight,
    const float* bias,
    float divisor,
    float* out,
    int B, int N, int K
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * N) return;
    int b = idx / N;
    int n = idx % N;
    float accum = bias[n];
    for (int k = 0; k < K; ++k) {
        accum += x[ b * K + k ] * weight[ n * K + k ];
    }
    float val = accum / divisor;
    out[ b * N + n ] = gelu(val);
}

torch::Tensor fused_linear_div_gelu_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double divisor
) {
    int B = x.size(0);
    int K = x.size(1);
    int N = weight.size(0);
    torch::Tensor out = torch::empty({B, N}, x.options());
    float div = static_cast<float>(divisor);
    const int BS = 256;
    dim3 block(BS);
    dim3 grid( (B * N + BS - 1) / BS );
    fused_linear_div_gelu_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        div,
        out.data_ptr<float>(),
        B, N, K
    );
    return out;
