__global__ void conv2d_kernel(const float* input, const float* filter, const float* bias, float* output,
    int batchSize, int inChannels, int inputHeight, int inputWidth,
    int outChannels, int filterHeight, int filterWidth, int outputHeight, int outputWidth) {
    int outputIdx = blockIdx.x * blockDim.x + threadIdx.x;
    int totalOutputElements = batchSize * outChannels * outputHeight * outputWidth;
    if (outputIdx &gt;= totalOutputElements) return;
    int outputWidth_times_outputHeight = outputHeight * outputWidth;
    int outChannelIdx = (outputIdx / outputWidth_times_outputHeight) % outChannels;
    int batchIdx = outputIdx / (outChannels * outputWidth_times_outputHeight);
    int outputPixelIdx = outputIdx % outputWidth_times_outputHeight;
    int heightIdx = outputPixelIdx / outputWidth;
    int widthIdx = outputPixelIdx % outputWidth;
    float accum = bias[outChannelIdx];
    for (int inChannelIdx = 0; inChannelIdx &lt; inChannels; ++inChannelIdx) {
        for (int filterRowIdx = 0; filterRowIdx &lt; filterHeight; ++filterRowIdx) {
            for (int filterColIdx = 0; filterColIdx &lt; filterWidth; ++filterColIdx) {
                int inputRowIdx = heightIdx + filterRowIdx;
                int inputColIdx = widthIdx + filterColIdx;
                if (inputRowIdx &lt; inputHeight &amp;&amp; inputColIdx &lt; inputWidth) {
                    float inputVal = input[((batchIdx * inChannels + inChannelIdx) * inputHeight + inputRowIdx) * inputWidth + inputColIdx];
                    float filterVal = filter[((outChannelIdx * inChannels + inChannelIdx) * filterHeight + filterRowIdx) * filterWidth + filterColIdx];
                    accum += inputVal * filterVal;
                }
            }
        }
    }
    output[outputIdx] = accum;
}

