    auto outputHeight = inputHeight - filterHeight + 1;
    auto outputWidth = inputWidth - filterWidth + 1;
    auto output = torch::empty({batchSize, outChannels, outputHeight, outputWidth}, input.options());
    int totalOutputElements = batchSize * outChannels * outputHeight * outputWidth;
    const int threadsPerBlock = 256;
    const int blocks = (totalOutputElements + threadsPerBlock - 1) / threadsPerBlock;
    conv2d_kernel&lt;&lt;&lt;blocks, threadsPerBlock&gt;&gt;&gt;(
        input.data_ptr&lt;float&gt;(),
        filter.data_ptr&lt;float&gt;(),
        bias.data_ptr&lt;float&gt;(),
        output.data_ptr&lt;float&gt;(),
