    int b = idx / (Cout * Hout * Wout);
    int remaining = idx % (Cout * Hout * Wout);
    int cout_ = remaining / (Hout * Wout);
    int oh = (remaining / Wout) % Hout;
    int ow = remaining % Wout;
    float acc = c_bias[cout_];
    for (int ci = 0; ci &lt; Cin; ++ci) {
        for (int kh = 0; kh &lt; Kh; ++kh) {
            for (int kw = 0; kw &lt; Kw; ++kw) {
                int h = oh + kh;
