#include <hip/hip_runtime.h>

__global__ void fused_reduce_kernel(const float* x, float* out, int B, int N, int k, float scale, int M) {
    int b = blockIdx.x;
    if (b >= B) return;
    int tx = threadIdx.x;
    const int TPB = 512;
    __shared__ float partial_sums[TPB];
    float thread_sum = 0.0f;
    const float* row = x + b * N;
    for (int i = tx; i < M; i += TPB) {
        float max_val = row[i * k];
        for (int j = 1; j < k; ++j) {
            max_val = fmaxf(max_val, row[i * k + j]);
        }
        thread_sum += max_val;
    }
    partial_sums[tx] = thread_sum;
    __syncthreads();
    for (int s = TPB / 2; s > 0; s >>= 1) {
        if (tx < s) {
            partial_sums[tx] += partial_sums[tx + s];
        }
        __syncthreads();
    }
    if (tx == 0) {
        out[b] = partial_sums[0] * scale;
    }
}

