    int64_t B = x.size(0);
    int64_t N = x.size(1);
    int64_t k = kernel_size_;
    int64_t M = N / k;
    torch::Tensor out = torch::zeros({B}, x.options());
    const int TPB = 512;
    dim3 grid(static_cast<unsigned int>(B));
    dim3 block(TPB);
    fused_reduce_kernel<<<grid, block>>>(x.data_ptr<float>(), out.data_ptr<float>(), static_cast<int>(B), static_cast<int>(N), static_cast<int>(k), scale, static_cast<int>(M));
    return out;
}
