    float *output,
    int B, int Ci, int D, int H, int W, 
    int Co, int kd, int kh, int kw, 
    int Do, int Ho, int Wo
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * Co * Do * Ho * Wo;
    if (idx >= total) return;
    int b = idx / (Co * Do * Ho * Wo);
    int rem1 = idx % (Co * Do * Ho * Wo);
    int co = rem1 / (Do * Ho * Wo);
    int rem2 = rem1 % (Do * Ho * Wo);
    int oz = rem2 / (Ho * Wo);
    int rem3 = rem2 % (Ho * Wo);
    int oy = rem3 / Wo;
    int ox = rem3 % Wo;
    float sum = bias[co];
    for (int ci = 0; ci < Ci; ci++) {
        for (int kz = 0; kz < kd; kz++) {
            int iz = oz + kz;
            if (iz >= D) continue;
            for (int ky = 0; ky < kh; ky++) {
                int iy = oy + ky;
                if (iy >= H) continue;
                for (int kx = 0; kx < kw; kx++) {
                    int ix = ox + kx;
                    if (ix >= W) continue;
                    size_t in_idx = ((size_t)b * Ci + ci) * (size_t)(D * H * W) +
                                    (size_t)iz * (H * W) + 
                                    (size_t)iy * W + ix;
                    size_t w_idx = ((size_t)co * Ci + ci) * (size_t)(kd * kh * kw) +
                                   (size_t)kz * (kh * kw) + 
                                   (size_t)ky * kw + kx;
                    sum += input[in_idx] * weight[w_idx];
                }
            }
        }
    }
    size_t out_idx = ((size_t)b * Co + co) * (size_t)(Do * Ho * Wo) +
                     (size_t)oz * (Ho * Wo) + 
                     (size_t)oy * Wo + ox;
    output[out_idx] = sum;
