    hipLaunchKernelGGL(conv2d_kernel, grid, block, 0, 0,
                       input.data_ptr<float>(),
                       weight.data_ptr<float>(),
                       bias.data_ptr<float>(),
                       output.data_ptr<float>(),
                       static_cast<int>(N), static_cast<int>(Cin), static_cast<int>(Cout),
                       static_cast<int>(Hin), static_cast<int>(Win), K,
                       static_cast<int>(out_h), static_cast<int>(out_w));
