    long long n_elems = B * N;
    const int threads = 256;
    int blocks = (n_elems + threads - 1) / threads;
    fused_linear_swish_bias_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(), weight.data_ptr<float>(),
        bias1.data_ptr<float>(), bias2.data_ptr<float>(),
        out.data_ptr<float>(), (int)B, (int)K, (int)N);
