    int B = x.size(0);
    int K = x.size(1);
    int N = weight.size(0);
    auto out = torch::empty({B, N}, x.options());
    int n_elems = B * N;
    int num_blocks = (n_elems + 255) / 256;
    fused_linear_gelu_kernel<<<num_blocks, 256>>>(x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), out.data_ptr<float>(), B, K, N);
    return out;
