fused_reduce_cpp = """
#include <hip/hip_runtime.h>

__global__ void fused_reduce_kernel(const float* x, float* out, int B, int N, int k, float scale, int M) {
    int b = blockIdx.x;
    if (b >= B) return;
    int tx = threadIdx.x;
    const int TPB = 1024;
    __shared__ float partial_sums[TPB];
    float thread_sum = 0.0f;
    const float* row = x + b * N;
    for (int i = tx; i < M; i += TPB) {
        float max_val = row[i * k];
        #pragma unroll
        for (int j = 1; j < k; ++j) {
            max_val = fmaxf(max_val, row[i * k + j]);
        }
        thread_sum += max_val;
    }
    partial_sums[tx] = thread_sum;
    __syncthreads();
    for (int s = TPB / 2; s > 0; s >>= 1) {
        if (tx < s) {
            partial_sums[tx] += partial_sums[tx + s];
        }
        __syncthreads();
    }
    if (tx == 0) {
        out[b] = partial_sums[0] * scale;
    }
}

torch::Tensor fused_reduce_hip(torch::Tensor x, int64_t kernel_size_, float scale) {
    int64_t B = x.size(0);
    int64_t N = x.size(1);
    int64_t k = kernel_size_;
    int64_t M = N / k;
    torch::Tensor out = torch::zeros({B}, x.options());
    const int TPB = 1024;
    dim3 grid(static_cast<unsigned int>(B));
    dim3 block(TPB);
    fused_reduce_kernel<<<grid, block>>>(x.data_ptr<float>(), out.data_ptr<float>(), static_cast<int>(B), static_cast<int>(N), static_cast<int>(k), scale, static_cast<int>(M));
    return out;
}
