#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_kernel(const float* x, float* out, float s1, float s2, size_t size) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx] - s1;
        out[idx] = tanhf(val) - s2;
    }
}

torch::Tensor fused_tanh_sub(torch::Tensor x, float s1, float s2) {
    auto out = torch::zeros_like(x);
    size_t size = x.numel();
    const size_t block_size = 1024;
    size_t num_blocks = (size + block_size - 1) / block_size;
    fused_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), s1, s2, size);
    return out;
}

__global__ void avgpool_kernel(const float* in, float* out, size_t B, size_t C, size_t H, size_t W) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    size_t out_H = H / 2;
    size_t out_W = W / 2;
    size_t out_numel = B * C * out_H * out_W;
    if (idx >= out_numel) return;
    size_t temp = idx;
    size_t b = temp / (C * out_H * out_W);
    temp %= (C * out_H * out_W);
    size_t c = temp / (out_H * out_W);
    temp %= (out_H * out_W);
    size_t oh = temp / out_W;
    size_t ow = temp % out_W;
    size_t ih = oh * 2;
    size_t iw = ow * 2;
    size_t base_idx = ((b * C + c) * H + ih) * W + iw;
    float sum = in[base_idx];
    sum += in[base_idx + 1];
    sum += in[base_idx + W];
    sum += in[base_idx + W + 1];
    out[idx] = sum / 4.0f;
}

torch::Tensor avgpool2d_hip(torch::Tensor x) {
    auto sizes = x.sizes();
    size_t B = sizes[0];
    size_t C = sizes[1];
    size_t H = sizes[2];
    size_t W = sizes[3];
    size_t out_H = H / 2;
    size_t out_W = W / 2;
    auto out = torch::empty({int64_t(B), int64_t(C), int64_t(out_H), int64_t(out_W)}, x.options());
    size_t out_numel = B * C * out_H * out_W;
    const size_t block_size = 1024;
    size_t num_blocks = (out_numel + block_size - 1) / block_size;
    avgpool_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), B, C, H, W);
    return out;
}

__global__ void conv_fused_kernel(const float *X, const float *W, const float *Bias, float *Y, size_t B, size_t Ci, size_t Hi, size_t Wi, size_t Co, float s1, float s2) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    size_t Ho = Hi - 2;
    size_t Wo = Wi - 2;
    size_t out_numel = B * Co * Ho * Wo;
    if (idx >= out_numel) return;
    size_t temp = idx;
    size_t b = temp / (Co * Ho * Wo);
    temp %= (Co * Ho * Wo);
    size_t co = temp / (Ho * Wo);
    temp %= (Ho * Wo);
    size_t ho = temp / Wo;
    size_t wo = temp % Wo;
    float acc = Bias ? Bias[co] : 0.0f;
    for (size_t ci = 0; ci < Ci; ++ci) {
        for (int kh = 0; kh < 3; ++kh) {
            size_t ih = ho + kh;
            for (int kw = 0; kw < 3; ++kw) {
                size_t iw = wo + kw;
                size_t xidx = ((b * Ci + ci) * Hi + ih) * Wi + iw;
                size_t widx = ((co * Ci + ci) * 3 + kh) * 3 + kw;
                acc += X[xidx] * W[widx];
            }
        }
    }
