__global__ void conv2d_kernel(const float* __restrict__ input, const float* __restrict__ weight, const float* __restrict__ bias, float* __restrict__ output,
                              const int N, const int Cin, const int Cout, const int Hin, const int Win, const int K, const int out_h, const int out_w) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride_spatial = out_h * out_w;
    int total_out = N * Cout * stride_spatial;
    if (idx >= total_out) return;
    int b_c = idx / stride_spatial;
    int b = b_c / Cout;
    int c = b_c % Cout;
    int spatial = idx % stride_spatial;
    int oh = spatial / out_w;
    int ow = spatial % out_w;
    float sum = bias[c];
#pragma unroll
    for (int cin = 0; cin < Cin; ++cin) {
#pragma unroll
        for (int ky = 0; ky < K; ++ky) {
            int ih = oh + ky;
#pragma unroll
            for (int kx = 0; kx < K; ++kx) {
