                float i_val = input[ ((b * Cin + cin) * Hin + ih) * Win + iw ];
                float w_val = weight[ ((c * Cin + cin) * K + ky) * K + kx ];
                sum += i_val * w_val;
            }
        }
    }
    int oidx = ((b * Cout + c) * out_h + oh) * out_w + ow;
    output[oidx] = sum;
}

