    auto out_h = Hin - K + 1;
    auto out_w = Win - K + 1;
    auto opts = input.options();
    auto output = torch::empty({N, Cout, out_h, out_w}, opts);
    int64_t total_out = N * Cout * out_h * out_w;
    const int block_size = 1024;
    dim3 block(block_size);
    dim3 grid( (total_out + block_size - 1) / block_size );
    hipLaunchKernelGGL(conv2d_kernel, grid, block, 0, 0,
                       input.data_ptr<float>(),
                       weight.data_ptr<float>(),
                       bias.data_ptr<float>(),
