#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void fused_conv_act_bn_kernel(const float* input, const float* w_conv, const float* b_conv, float* output,
    const float* running_mean, const float* running_var, const float* gamma, const float* beta, float eps,
    int64_t N, int64_t Co, int64_t Ho, int64_t Wo, int64_t Ci, int64_t Hi, int64_t Wi, int64_t Kh, int64_t Kw) {
    size_t idx = size_t(blockIdx.x) * size_t(blockDim.x) + size_t(threadIdx.x);
    size_t stride_nchw = size_t(Co) * size_t(Ho) * size_t(Wo);
    if (idx >= size_t(N) * stride_nchw) return;
    size_t temp = idx % stride_nchw;
    int64_t n = idx / stride_nchw;
    int64_t c = temp / (size_t(Ho) * Wo);
    int64_t hw = temp % (size_t(Ho) * Wo);
    int64_t h = hw / Wo;
    int64_t w = hw % Wo;
    float acc = b_conv[c];
    for (int64_t ci = 0; ci < Ci; ++ci) {
        for (int64_t kh = 0; kh < Kh; ++kh) {
            int64_t ih = h + kh;
            for (int64_t kw = 0; kw < Kw; ++kw) {
                int64_t iw = w + kw;
                float i_val = input[(n * Ci + ci) * Hi * Wi + ih * Wi + iw];
                float w_val = w_conv[(c * Ci + ci) * Kh * Kw + kh * Kw + kw];
                acc += i_val * w_val;
            }
        }
    }
    float x = acc;
    float sp = (x > 0.0f) ? (x + log1pf(expf(-x))) : log1pf(expf(x));
    float act_out = tanhf(sp) * x;
    float mean_c = running_mean[c];
    float var_c = running_var[c];
    float denom = sqrtf(var_c + eps);
    float xhat = (act_out - mean_c) / denom;
    int64_t out_offset = (n * Co + c) * Ho * Wo + h * Wo + w;
    output[out_offset] = xhat * gamma[c] + beta[c];
}

torch::Tensor fused_conv_act_bn_hip(torch::Tensor input, torch::Tensor w_conv, torch::Tensor b_conv,
    torch::Tensor running_mean, torch::Tensor running_var, torch::Tensor gamma, torch::Tensor beta, float eps) {
    int64_t N = input.size(0);
    int64_t Ci = input.size(1);
    int64_t Hi = input.size(2);
    int64_t Wi = input.size(3);
    int64_t Co = w_conv.size(0);
    int64_t Kh = w_conv.size(2);
    int64_t Kw = w_conv.size(3);
    int64_t Ho = Hi - Kh + 1;
    int64_t Wo = Wi - Kw + 1;
