fused_cpp = r"""
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <algorithm>
#include <math.h>

const int TILE_N = 64;
const int KTILE = 128;

__global__ void fused_tiled_kernel(const float* A, const float* W, const float* b, float scale, float* C, int B, int N, int K) {
    __shared__ float sA[KTILE];
    __shared__ float sWB[TILE_N][KTILE];

    int b_idx = blockIdx.x;
    int nt_idx = blockIdx.y;
    int n_start = nt_idx * TILE_N;
    int tid = threadIdx.x;
    int j = n_start + tid;
    if (b_idx >= B || j >= N) return;

    float acc = b[j];

    for (int k_panel = 0; k_panel < K; k_panel += KTILE) {
        int k_panel_size = std::min(KTILE, K - k_panel);

        // Load input panel to shared memory, 2 loads per thread
        int idx0 = k_panel + tid * 2;
        int idx1 = idx0 + 1;
        if (tid * 2 < k_panel_size) {
            sA[tid * 2] = A[b_idx * K + idx0];
        }
        if (tid * 2 + 1 < k_panel_size) {
            sA[tid * 2 + 1] = A[b_idx * K + idx1];
        }
        __syncthreads();

        // Load weight panel serially
        for (int lk = 0; lk < k_panel_size; ++lk) {
            sWB[tid][lk] = W[j * K + k_panel + lk];
        }
        __syncthreads();

        // Compute partial sum
#pragma unroll 4
        for (int lk = 0; lk < k_panel_size; lk += 4) {
            acc += sA[lk + 0] * sWB[tid][lk + 0];
            acc += sA[lk + 1] * sWB[tid][lk + 1];
            acc += sA[lk + 2] * sWB[tid][lk + 2];
            acc += sA[lk + 3] * sWB[tid][lk + 3];
        }
    }

    float val = acc;
    float sig = 1.0f / (1.0f + expf(-val));
    C[b_idx * N + j] = val * sig * scale;
}

torch::Tensor fused_tiled_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, torch::Tensor scale_t) {
    int64_t BB = input.size(0);
    int64_t KK = input.size(1);
    int64_t NN = weight.size(0);
    int B = static_cast<int>(BB);
    int N = static_cast<int>(NN);
    int K = static_cast<int>(KK);
    auto output = torch::empty({BB, NN}, input.options());
    float scale = *scale_t.data_ptr<float>();
    dim3 block(TILE_N);
    dim3 grid(B, (N + TILE_N - 1) / TILE_N);
    fused_tiled_kernel<<<grid, block>>>(input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), scale, output.data_ptr<float>(), B, N, K);
    return output;
}
"""

