__global__ void fused_kernel(const float *x, const float *w, const float *b, float *out, float sf, int B, int K, int N) {
    int batch_idx = blockIdx.y;
    if (batch_idx >= B) return;
    int out_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (out_idx >= N) return;
    float acc = 0.0f;
    const int x_off = batch_idx * K;
    const int w_off = out_idx * K;
    for (int k = 0; k < K; ++k) {
        acc += x[x_off + k] * w[w_off + k];
    }
    acc += b[out_idx];
    out[batch_idx * N + out_idx] = acc * (sf + 1.0f);
}

