    int ty = threadIdx.x / 32;
    int row = blockIdx.y * 32 + tx;
    int col = blockIdx.x * 32 + ty;
    float acc = 0.0f;
    const int KTS = 16;
    int num_tiles = (K + KTS - 1) / KTS;
    for (int tile = 0; tile < num_tiles; ++tile) {
        if (row < M) {
            As[tx][ty] = x[row * K + tile * KTS + ty];
        } else {
            As[tx][ty] = 0.0f;
