    float scale = *scale_t.data_ptr<float>();
    dim3 block(TILE_N);
    dim3 grid(B, (N + TILE_N - 1) / TILE_N);
    fused_tiled_kernel<<<grid, block>>>(input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), scale, output.data_ptr<float>(), B, N, K);
    return output;
