                       bias.data_ptr<float>(),
                       output.data_ptr<float>(),
                       static_cast<int>(N), static_cast<int>(Cin), static_cast<int>(Cout),
                       static_cast<int>(Hin), static_cast<int>(Win),
                       out_h, out_w,
                       static_cast<int>(num_oh_tiles), static_cast<int>(num_ow_tiles));
    return output;
}
