__global__ void fused_conv_tanh_scale_bias_kernel(
    const float* input,
    const float* weight,
    const float* c_bias,
    float scale,
    const float* a_bias,
    float* output,
    int B, int Cin, int Cout,
    int Hin, int Win, int Hout, int Wout,
    int Kh, int Kw
) {
    constexpr int TILE_OH = 8;
    constexpr int TILE_OW = 32;
    constexpr int IH_PAD = 16;
    constexpr int IW_PAD = 48;
    __shared__ float s_spatial[IH_PAD * IW_PAD];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;
    int tile_oh = blockIdx.y;
    int tile_ow = blockIdx.x;
    int bcid = blockIdx.z;
    int b = bcid / Cout;
    int cout_ = bcid % Cout;
    int oh = tile_oh * TILE_OH + ty;
    int ow = tile_ow * TILE_OW + tx;

    int h_base = tile_oh * TILE_OH;
    int w_base = tile_ow * TILE_OW;
    float acc = 0.0f;
    bool valid = (oh < Hout && ow < Wout);
    if (valid) {
        acc = c_bias[cout_];
    }

    for (int ci = 0; ci < Cin; ++ci) {
        int sh_size = IH_PAD * IW_PAD;
        for (int i = tid; i < sh_size; i += blockDim.x * blockDim.y) {
            int lh = i / IW_PAD;
            int lw = i % IW_PAD;
            int gh = h_base + lh;
            int gw = w_base + lw;
            float val = 0.0f;
            if (gh >= 0 && gh < Hin && gw >= 0 && gw < Win) {
                val = input[((b * Cin + ci) * Hin + gh) * Win + gw];
            }
            s_spatial[i] = val;
        }
        __syncthreads();

        if (valid) {
            #pragma unroll
            for (int kh = 0; kh < Kh; ++kh) {
                #pragma unroll
                for (int kw = 0; kw < Kw; ++kw) {
                    int lh = ty + kh;
                    int lw = tx + kw;
                    if (lh < IH_PAD && lw < IW_PAD) {
                        float in_val = s_spatial[lh * IW_PAD + lw];
                        float w_val = weight[((cout_ * Cin + ci) * Kh + kh) * Kw + kw];
                        acc += in_val * w_val;
                    }
                }
            }
        }
        __syncthreads();
    }
    if (valid) {
        float act = tanhf(acc);
        int out_idx = ((b * Cout + cout_) * Hout + oh) * Wout + ow;
        output[out_idx] = act * scale + a_bias[cout_];
    }
}

torch::Tensor fused_conv_tanh_scale_bias_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor c_bias,
    float scale,
