    int64_t Kh = desc[2];
    int64_t Kw = desc[3];
    int64_t Hout = Hin - Kh + 1;
    int64_t Wout = Win - Kw + 1;
    torch::Tensor out = torch::zeros({B, Cout, Hout, Wout}, input_c.options());

