        (int)Co, (int)kd, (int)kh, (int)kw,
        (int)Do, (int)Ho, (int)Wo);
    hipDeviceSynchronize();
    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        printf("HIP error after launch: %s\\n", hipGetErrorString(err));
    }
    return out;
}
