__device__ float gelu(float x) {
    constexpr float k1 = 0.7978845608f;
    constexpr float k2 = 0.044715f;
    float x3 = x * x * x;
    float inner = k1 * (x + k2 * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

__global__ void tiled_fused_linear_div_gelu_kernel(
    const float* x,
    const float* weight,
    const float* bias,
    float divisor,
    float* out,
    int B, int N, int K
) {
    constexpr int TM = 32;
    constexpr int TN = 32;
    constexpr int TK = 64;
    __shared__ float As[TM][TK];
    __shared__ float Bs[TK][TN];

    int b_start = blockIdx.y * TM;
    int n_start = blockIdx.x * TN;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * TN + tx;
    int b_global = b_start + ty;
    int n_global = n_start + tx;
    if (b_global >= B || n_global >= N) return;

    float accum = bias[n_global];

    for (int tk = 0; tk < K; tk += TK) {
        // Load A tile (x)
        for (int p = 0; p < 2; ++p) {
            int lid = tid + p * (TN * TM);
            if (lid < TM * TK) {
                int row = lid / TK;
                int col = lid % TK;
                As[row][col] = (tk + col < K) ? x[(b_start + row) * K + tk + col] : 0.0f;
            }
        }
        // Load B tile (weight)
        for (int p = 0; p < 2; ++p) {
            int lid = tid + p * (TN * TM);
            if (lid < TK * TN) {
                int row_b = lid / TN;
                int col_b = lid % TN;
                int g_n = n_start + col_b;
                int g_k = tk + row_b;
                Bs[row_b][col_b] = (g_k < K) ? weight[g_n * K + g_k] : 0.0f;
            }
        }
        __syncthreads();

        int kmax = min(TK, K - tk);
        for (int k = 0; k < kmax; ++k) {
            accum += As[ty][k] * Bs[k][tx];
        }
        __syncthreads();
    }

    float val = accum / divisor;
    out[b_global * N + n_global] = gelu(val);
}

