__device__ float gelu(float x) {
    constexpr float k1 = 0.7978845608f;
    constexpr float k2 = 0.044715f;
    float x3 = x * x * x;
    float inner = k1 * (x + k2 * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

__global__ void tiled_fused_linear_div_gelu_kernel(
    const float* x,
    const float* weight,
    const float* bias,
    float divisor,
    float* out,
    int B, int N, int K
) {
    constexpr int TM = 32;
    constexpr int TN = 32;
    constexpr int TK = 128;
    constexpr int BS = TM * TN;
    __shared__ float As[TM][TK];
    __shared__ float Bs[TK][TN];

    int b_start = blockIdx.y * TM;
    int n_start = blockIdx.x * TN;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * TN + tx;
    int b = b_start + ty;
    int n = n_start + tx;
    if (b >= B || n >= N) return;

    float accum = bias[n];

    for (int tk = 0; tk < K; tk += TK) {
        // Load A unrolled
        int lid = tid;
        if (lid < TM * TK) {
            int row = lid / TK;
            int col = lid % TK;
            As[row][col] = x[(b_start + row) * K + tk + col];
        }
        lid += BS;
        if (lid < TM * TK) {
            int row = lid / TK;
            int col = lid % TK;
            As[row][col] = x[(b_start + row) * K + tk + col];
        }
        lid += BS;
        if (lid < TM * TK) {
            int row = lid / TK;
            int col = lid % TK;
            As[row][col] = x[(b_start + row) * K + tk + col];
        }
        lid += BS;
        if (lid < TM * TK) {
            int row = lid / TK;
            int col = lid % TK;
            As[row][col] = x[(b_start + row) * K + tk + col];
        }
        // Load B unrolled
        lid = tid;
        if (lid < TK * TN) {
            int row_b = lid / TN;
            int col_b = lid % TN;
            int g_n = n_start + col_b;
            Bs[row_b][col_b] = weight[g_n * K + tk + row_b];
        }
        lid += BS;
        if (lid < TK * TN) {
            int row_b = lid / TN;
            int col_b = lid % TN;
            int g_n = n_start + col_b;
            Bs[row_b][col_b] = weight[g_n * K + tk + row_b];
        }
        lid += BS;
        if (lid < TK * TN) {
            int row_b = lid / TN;
            int col_b = lid % TN;
            int g_n = n_start + col_b;
            Bs[row_b][col_b] = weight[g_n * K + tk + row_b];
        }
        lid += BS;
        if (lid < TK * TN) {
            int row_b = lid / TN;
            int col_b = lid % TN;
            int g_n = n_start + col_b;
            Bs[row_b][col_b] = weight[g_n * K + tk + row_b];
        }
        __syncthreads();

        int kmax = (TK < K - tk) ? TK : (K - tk);
        for (int k = 0; k < kmax; ++k) {
            accum += As[ty][k] * Bs[k][tx];
        }
        __syncthreads();
    }
    out[b * N + n] = gelu(accum / divisor);
}

