    int64_t Cin = desc[1];
    int64_t Hin = desc[2];
    int64_t Win = desc[3];
    desc = weight.sizes();
    int64_t Cout = desc[0];
    int64_t Kh = desc[2];
    int64_t Kw = desc[3];
    int64_t Hout = Hin - Kh + 1;
    int64_t Wout = Win - Kw + 1;
    torch::Tensor out = torch::zeros({B, Cout, Hout, Wout}, input.options());
    int64_t total = B * Cout * Hout * Wout;
    const int bsize = 1024;
    const int64_t nblocks = (total + bsize - 1) / bsize;
    fused_conv_tanh_scale_bias_kernel<<<nblocks, bsize>>>(
