#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>
#include <limits>

__global__ void fused_conv_tanh_scale_bias_pool_kernel(const float* input, const float* weight, const float* c_bias, float scale, const float* a_bias, float* output, int B, int Cin, int Cout, int Hin, int Win, int Hout, int Wout, int Kh, int Kw) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int Ph = (Hout - 4) / 4 + 1;
    int Pw = (Wout - 4) / 4 + 1;
    int total = B * Cout * Ph * Pw;
    if (idx >= total) return;
    int b = idx / (Cout * Ph * Pw);
    int remaining = idx % (Cout * Ph * Pw);
    int cout_ = remaining / (Ph * Pw);
    int ph = (remaining / Pw) % Ph;
    int pw = remaining % Pw;
    float maxv = -std::numeric_limits<float>::infinity();
    for (int doh = 0; doh < 4; ++doh) {
        int oh = ph * 4 + doh;
        if (oh >= Hout) continue;
        for (int dow = 0; dow < 4; ++dow) {
            int ow = pw * 4 + dow;
            if (ow >= Wout) continue;
            float acc = c_bias[cout_];
            for (int ci = 0; ci < Cin; ++ci) {
                for (int kh = 0; kh < Kh; ++kh) {
                    for (int kw = 0; kw < Kw; ++kw) {
                        int h = oh + kh;
                        int w = ow + kw;
                        float in_val = input[ ((b * Cin + ci) * Hin + h) * Win + w ];
                        float w_val = weight[ ((cout_ * Cin + ci) * Kh + kh) * Kw + kw ];
                        acc += in_val * w_val;
                    }
                }
            }
            float temp = tanhf(acc) * scale;
            if (temp > maxv) maxv = temp;
        }
    }
    int out_idx = ((b * Cout + cout_) * Ph + ph) * Pw + pw;
    output[out_idx] = maxv + a_bias[cout_];
}

torch::Tensor fused_full_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor c_bias,
    float scale,
    torch::Tensor a_bias
) {
    auto desc = input.sizes();
    int64_t B = desc[0];
    int64_t Cin = desc[1];
    int64_t Hin = desc[2];
    int64_t Win = desc[3];
    desc = weight.sizes();
    int64_t Cout = desc[0];
    int64_t Kh = desc[2];
    int64_t Kw = desc[3];
    int64_t Hout = Hin - Kh + 1;
    int64_t Wout = Win - Kw + 1;
    int64_t Ph = (Hout - 4) / 4 + 1;
    int64_t Pw = (Wout - 4) / 4 + 1;
    torch::Tensor out = torch::zeros({B, Cout, Ph, Pw}, input.options());
    int64_t total = B * Cout * Ph * Pw;
    const int bsize = 256;
    const int64_t nblocks = (total + bsize - 1) / bsize;
    fused_conv_tanh_scale_bias_pool_kernel<<<nblocks, bsize>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        c_bias.data_ptr<float>(),
        scale,
        a_bias.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)B, (int)Cin, (int)Cout, (int)Hin, (int)Win, (int)Hout, (int)Wout, (int)Kh, (int)Kw
    );
    return out;
}
